/** Logistic weights over `featureVector` (generated by tools/crop/fit.py; do not edit by hand). */
export interface CropModel {
  version: string;
  /** Ranking weights over `featureVector` (softmax per photo). */
  weights: number[];
  /** Confidence = sigmoid(c0 + c1 · top score + c2 · (top − runner-up)). */
  calibration: [number, number, number];
  /** Auto-apply at or above this confidence (chosen for >= 98% precision on tune photos). */
  autoThreshold: number;
}

